PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY, title TEXT NOT NULL, goal TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nodes(id TEXT PRIMARY KEY, name TEXT NOT NULL, caps TEXT, checked_in INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS local_node_keys(hash TEXT PRIMARY KEY, node_id TEXT NOT NULL REFERENCES nodes(id), revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pairing(id INTEGER PRIMARY KEY CHECK(id=1), hash TEXT NOT NULL, expires INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS cards(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), key TEXT NOT NULL, data TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ready', reason TEXT, UNIQUE(project_id,key));
CREATE TABLE IF NOT EXISTS leases(card_id TEXT PRIMARY KEY REFERENCES cards(id), node_id TEXT NOT NULL UNIQUE REFERENCES nodes(id), session TEXT NOT NULL, expires INTEGER NOT NULL, ttl INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS card_outputs(card_id TEXT PRIMARY KEY REFERENCES cards(id), node_id TEXT NOT NULL, session TEXT NOT NULL, content TEXT NOT NULL, model_id TEXT, usage TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checkpoints(card_id TEXT PRIMARY KEY REFERENCES cards(id), step INTEGER NOT NULL, state TEXT NOT NULL, usage TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS child_links(parent TEXT NOT NULL REFERENCES cards(id), child TEXT NOT NULL REFERENCES cards(id), PRIMARY KEY(parent,child));
CREATE TABLE IF NOT EXISTS mcp_servers(id TEXT PRIMARY KEY, config TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS activity(id INTEGER PRIMARY KEY, node_id TEXT NOT NULL, kind TEXT NOT NULL, body TEXT NOT NULL, payload TEXT NOT NULL, created INTEGER NOT NULL);
PRAGMA user_version=1;
